=vb vb=false ub.spoilerName=vb vb=true ub.sendServerHops=vb vb=false ub.sendArrest=vb vb=true ub.sendSessionTime=vb ub.sendServer=vb vb=0 ub.lastSent=vb tb=ub tb={[0b11]=1,[1]=tb}tb[0b10]=tb ub=nil ub={[0b11]=1,[1]=ub}ub[0b10]=ub vb={[0b11]=1,[1]=vb}vb[0b10]=vb vb[0b10][vb[0b11]]=a:B{K,M,r,tb,L,q,pb,S}wb={[0b11]=1,[1]=wb}wb[0b10]=wb wb[0b10][wb[0b11]]=a:W{tb,n,u,vb}xb={[0b11]=1,[1]=xb}xb[0b10]=xb Ab,Bb,xb[0b10][xb[0b11]]={},"Help",a:P{ub,tb,wb}Ab.Title=Bb Bb="help-circle"Ab.Icon=Bb yb,zb=kb.Tab,kb yb=yb(zb,Ab)lb.Help=yb Bb,Ab,yb="Pick a topic",{},lb.Help Ab.Title=Bb yb,zb=yb.Section,yb yb(zb,Ab)Ab,zb="Open a tab on the left, flip a toggle on, and the script does the work.\nYour choices save automatically \226\128\148 next time you run the script, everything is how you left it.\nOn mobile, a floating OPEN UI button lets you hide and show this menu.",{}zb["Getting Started"]=Ab Ab="ATM Autofarm: walks to ATMs, robs them, repeat. Leave it on and go do something else.\nAuto Dropoff: every few ATMs it drives to the drop-off and cashes in your money so you don't lose it when you die.\nAuto Bail: if a Security NPC gets close to you, the script bails out instead of getting caught.\nDrop Off Now: cash in right now, without waiting for the next auto drop-off."zb["ATM Farm"]=Ab Ab="Turns you into a cop bot: finds a wanted player, chases them, and cuffs them.\nAuto Hop: if there are no wanted players in the server, hop to a new one and pick up Auto Arrest right where it left off \226\128\148 leave it on overnight and it'll keep finding fresh servers to farm bounties in.\nNext Player: you don't like the current target? Tap this to skip to a different one."zb["Auto Arrest"]=Ab Ab="Lets another player arrest you so they get the bounty reward. Good for trading bounty with a friend.\nMin Bounty: only trigger if your bounty is at least this high. Set to 0 to always trigger.\nSurrender To: type a username so only that player can collect. Leave empty for anyone."zb["Give Back"]=Ab Ab="A live scoreboard for your current session. Shows session time, criminals followed, server hops, and delivery stats (drop-offs completed, total earned, avg per delivery, $/hr).\nRefresh Stats: force the numbers to update if they look stuck."zb.Stats=Ab Ab="Sends your stats to a Discord channel on a timer, so you can watch progress from your phone.\n1) In Discord: Server Settings \226\134\146 Integrations \226\134\146 Webhooks \226\134\146 New Webhook \226\134\146 Copy URL.\n2) Paste the URL into 'Webhook URL' here.\n3) Turn on 'Enable Webhook'. Pick how often it should post under 'Send Interval'.\nSend Now: post an update immediately so you can check it's working."zb["Settings \226\128\148 Webhook"]=Ab Ab="Spoiler Player Name: hides your username behind Discord's black spoiler bars, so people who see the channel can't read it unless they click.\nData To Include: each toggle is one type of stat. Turn off anything you don't want showing up in Discord."zb["Settings \226\128\148 Privacy & Data"]=Ab Ab="Enable Auto Delivery and the script handles the whole delivery job loop for you \226\128\148 no setup needed.\nIt starts a delivery session, teleports to the package pickup, waits to collect all packages, then teleports to the drop-off and delivers them. Repeats until you turn it off.\nEarnings are tracked in the Stats tab: total earned, per-delivery average, and $/hr."zb.Delivery=Ab Ab="Sit in any car, then enable Auto Drive \226\128\148 the script steers it along a fixed 6-point route in reverse to rack up miles/studs driven.\nIf you're not in a car when you enable it, a prompt will ask you to spawn one. The script won't spawn or delete cars itself.\nMiles count because the car is physically driven on the ground by the game engine, not teleported."zb["Auto Drive"]=Ab Ab="Use Hold E: the old way of robbing ATMs. It's slower, but works on executors where the fast method fails. Turn it on if ATM Autofarm seems broken."zb["Settings \226\128\148 Farming"]=Ab yb=zb yb={[0b11]=